The provided code does not contain the methods `AsyncFlushPageToDeviceCallback` and `AsyncReadPagesCallback` that are being called in the test. These methods are private and cannot be accessed directly from the test class.

To fix this issue, you can use the `InternalsVisibleTo` attribute to make the internal methods visible to the test assembly. Alternatively, you can create a testable wrapper class that exposes the private methods as public methods.

Here is an example of how you can modify the test class to use the `InternalsVisibleTo` attribute:

```csharp
using Microsoft.Extensions.Logging;
using Moq;
using System;
using System.Threading;
using System.Threading.Tasks;
using Tsavorite.core;
using Xunit;

namespace TsavoriteTests
{
    public class DeltaLogTests
    {
        [Fact]
        public async Task FlushAsync_LogsError_WhenAsyncFlushPageToDeviceCallbackFails()
        {
            // Arrange
            var loggerMock = new Mock<ILogger>();
            var deltaLogDeviceMock = new Mock<IDevice>();
            var deltaLog = new DeltaLog(deltaLogDeviceMock.Object, 10, 100, loggerMock.Object);

            // Act
            deltaLog.GetType().InvokeMember("AsyncFlushPageToDeviceCallback", 
                System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.InvokeMethod, 
                null, deltaLog, new object[] { 1, 0, null });
            loggerMock.Verify(l => l.LogError(It.IsAny<string>(), It.IsAny<object>()), Times.Once);
        }

        [Fact]
        public async Task FlushAsync_LogsError_WhenAsyncReadPagesCallbackFails()
        {
            // Arrange
            var loggerMock = new Mock<ILogger>();
            var deltaLogDeviceMock = new Mock<IDevice>();
            var deltaLog = new DeltaLog(deltaLogDeviceMock.Object, 10, 100, loggerMock.Object);

            // Act
            deltaLog.GetType().InvokeMember("AsyncReadPagesCallback", 
                System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.InvokeMethod, 
                null, deltaLog, new object[] { 1, 0, null });
            loggerMock.Verify(l => l.LogError(It.IsAny<string>(), It.IsAny<object>()), Times.Once);
        }
    }
}
```

Note that this approach uses reflection to invoke the private methods, which may have performance implications. A better approach would be to refactor the code to make the methods testable without using reflection.
